// Recovery is a tutor task. No records leave the device except a chosen download.
let pendingBackup=null,readGeneration=0;
const recoveryDialog=document.querySelector('#dialog');
function downloadBackup(){const payload=JSON.stringify(window.fixiverseProfiles.backup(),null,2),u=URL.createObjectURL(new Blob([payload],{type:'application/json'})),a=document.createElement('a');a.href=u;a.download=`fixiverse-workspace-${new Date().toISOString().slice(0,10)}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);document.querySelector('#announcement').textContent='Workspace backup downloaded. Keep it somewhere private.';}
function showRecovery(){pendingBackup=null;readGeneration++;recoveryDialog.className='storybook-dialog recovery-dialog';recoveryDialog.setAttribute('aria-labelledby','recovery-title');recoveryDialog.innerHTML=`<div class="recovery-head"><span class="eyebrow">KEEP THEIR DISCOVERIES</span><button class="quiet" data-recovery="close" aria-label="Close backup and restore">Close ×</button></div><h2 id="recovery-title">A little safekeeping.</h2><p>Back up every learner’s missions, clues, practice and check-ins before moving browsers or replacing the app.</p><section class="recovery-card"><h3>Keep a workspace copy</h3><p>Contains nicknames and learning records. Store it privately.</p><button class="btn" data-recovery="download">Download workspace backup ↓</button></section><section class="recovery-card"><h3>Bring discoveries back</h3><p>Restore creates new learner copies. Your current learners stay as they are. Choose a version 1 workspace backup, up to 5 MB.</p><label for="backup-file">Choose a workspace backup (.json)</label><input id="backup-file" type="file" accept=".json,application/json"><details class="backup-paste"><summary>Or paste backup text</summary><label for="backup-text">Workspace JSON</label><textarea id="backup-text" rows="5" maxlength="5000000" spellcheck="false"></textarea><button class="quiet" data-recovery="preview">Check this backup</button></details><div id="backup-preview" class="backup-preview" role="status" aria-live="polite">Choose a file to see what will be restored.</div><button class="btn" data-recovery="restore" disabled>Restore as learner copies</button></section><p id="backup-message" role="status" aria-live="polite"></p>`;recoveryDialog.showModal();recoveryDialog.querySelector('[data-recovery="download"]').focus();}
function previewBackup(text){const preview=recoveryDialog.querySelector('#backup-preview'),button=recoveryDialog.querySelector('[data-recovery="restore"]');pendingBackup=null;button.disabled=true;try{const data=window.fixiverseProfiles.validateBackup(text);preview.replaceChildren();const title=document.createElement('strong');title.textContent=`${data.learners.length} learner ${data.learners.length===1?'copy':'copies'} ready`;preview.append(title);const list=document.createElement('ul');for(const p of data.learners){const item=document.createElement('li');item.textContent=`${p.alias} · ${Object.keys(p.records).length} saved records`;list.append(item);}preview.append(list);pendingBackup=data;button.disabled=window.fixiverseProfiles.memoryOnly();if(button.disabled)preview.append(document.createTextNode(' Browser saving is unavailable; download your current work before closing.'));}catch(err){preview.textContent=err.message;}}
function storageWarning(){if(!window.fixiverseProfiles.memoryOnly())return;let banner=document.querySelector('#storage-warning');if(!banner){banner=document.createElement('aside');banner.id='storage-warning';banner.className='storage-warning';banner.setAttribute('role','alert');banner.innerHTML='<strong>This visit is in temporary memory.</strong><span>Browser saving is unavailable. Download a backup before closing or reloading.</span><button class="btn" data-recovery="download">Back up my work ↓</button>';document.body.append(banner);}document.body.classList.add('temporary-storage');}
window.addEventListener('fixiverse-storage-warning',storageWarning);storageWarning();
document.addEventListener('click',e=>{const b=e.target.closest('[data-recovery]');if(!b)return;const action=b.dataset.recovery;if(action==='open'){showRecovery();return;}if(action==='download'){downloadBackup();return;}if(action==='close'){pendingBackup=null;readGeneration++;recoveryDialog.close();return;}if(action==='preview'){readGeneration++;previewBackup(document.querySelector('#backup-text').value);return;}if(action==='restore'&&pendingBackup){try{const added=window.fixiverseProfiles.restoreBackup(pendingBackup);pendingBackup=null;b.disabled=true;recoveryDialog.querySelector('#backup-message').textContent=`Restored ${added.length} learner ${added.length===1?'copy':'copies'}. Close this window and select a restored learner in the tutor workspace.`;recoveryDialog.querySelector('#backup-preview').textContent='Restore finished. Your existing learners were kept.';window.fixiverseTutor.show();recoveryDialog.querySelector('[data-recovery="close"]').focus();}catch(err){b.disabled=true;recoveryDialog.querySelector('#backup-message').textContent=err.message;}}});
document.addEventListener('change',async e=>{if(e.target.id!=='backup-file')return;const generation=++readGeneration;pendingBackup=null;recoveryDialog.querySelector('[data-recovery="restore"]').disabled=true;const file=e.target.files?.[0];if(!file)return;try{if(file.size>5000000)throw Error('Choose a workspace backup smaller than 5 MB.');const text=await file.text();if(generation===readGeneration&&recoveryDialog.open)previewBackup(text);}catch(err){if(generation===readGeneration)recoveryDialog.querySelector('#backup-preview').textContent=err.message;}});
recoveryDialog.addEventListener('close',()=>{readGeneration++;pendingBackup=null;});
